19	std::complex<double> L1(double x, double y) {
20	  double denom = one - x / y;
21	  if (std::abs(denom) < 1e-7) {
22	    return -half * cone - cplx1(denom / three * (one + 0.75 * denom));
23	  } else {
24	    return (L0(x, y) + cone) / cplx1(denom);
25	  }
26	}
