50	std::complex<double> Lsm1(double x1, double y1, double x2, double y2) {
51	  double r1 = x1 / y1;
52	  double r2 = x2 / y2;
53	  double omr1 = one - r1;
54	  double omr2 = one - r2;
55	  std::complex<double> dilog1, dilog2;
56	
57	  if (omr1 > one) {
58	    dilog1 = cplx1(pisqo6 - ddilog(r1)) - lnrat(x1, y1) * cplx1(std::log(omr1));
59	  } else {
60	    dilog1 = cplx1(ddilog(omr1));
61	  }
62	
63	  if (omr2 > one) {
64	    dilog2 = cplx1(pisqo6 - ddilog(r2)) - lnrat(x2, y2) * cplx1(std::log(omr2));
65	  } else {
66	    dilog2 = cplx1(ddilog(omr2));
67	  }
68	
69	  return dilog1 + dilog2 + lnrat(x1, y1) * lnrat(x2, y2) - cplx1(pisqo6);
70	}
