72	std::complex<double> Ls0(double x1, double y1, double x2, double y2) {
73	  double r1 = x1 / y1;
74	  double r2 = x2 / y2;
75	  return Lsm1(x1, y1, x2, y2) / cplx1(one - r1 - r2);
