84	std::complex<double> Ls2(double x1, double y1, double x2, double y2) {
85	  double r1 = x1 / y1;
86	  double r2 = x2 / y2;
87	  return (Ls1(x1, y1, x2, y2) + (L1(x1, y1) + L1(x2, y2)) / 2.0) /
88	         cplx1(one - r1 - r2);
89	}
