125	std::complex<double> Lsm1_2mh(double s, double t, double m1sq, double m2sq) {
126	  return Lsm1_2mht(s, t, m1sq, m2sq) +
127	         (half * (s - m1sq - m2sq) + m1sq * m2sq / t) * i3m(s, m1sq, m2sq);
128	}
